<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>PT Contoh — Company Profile</title>
<style>
  :root { --brand:#1a5fb4; --ink:#1f2937; --bg:#f8fafc; }
